1	package relayproof
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"strings"
10		"testing"
11	)
12	
13	// Regression coverage for stream-level interruptions: the error a caller
14	// receives must stay distinguishable from a single invalid log line, the
15	// failure count must cover only lines that failed normalization, and read
16	// failures must not be masked by later write failures. All fault injection
17	// is in-process and scripted, so the behavior reproduces deterministically
18	// without real pipes, networks, or device failures.
19	
20	var (
21		errSimulatedRead  = errors.New("simulated input device read failure")
22		errSimulatedWrite = errors.New("simulated output device write failure")
23	)
24	
25	// scriptReader replays fixed (data, err) Read results in order. A step may
26	// return data together with an error, mirroring a reader that loses its
27	// underlying device after delivering a truncated final fragment. After the
28	// script is exhausted every further Read returns io.EOF.
29	type scriptReader struct {
30		steps []scriptStep
31		i     int
32	}
33	
34	type scriptStep struct {
35		data []byte
36		err  error
37	}
38	
39	func (s *scriptReader) Read(p []byte) (int, error) {
40		if s.i >= len(s.steps) {
41			return 0, io.EOF
42		}
43		step := s.steps[s.i]
44		s.i++
45		n := copy(p, step.data)
46		if n < len(step.data) {
47			panic("scriptReader step larger than the caller's buffer; shrink the script data")
48		}
49		return n, step.err
50	}
51	
52	// failWriter accepts exactly allowBytes bytes in total, then fails. From the
53	// failing Write up to partial bytes are still recorded, so tests can model
54	// output cut off mid-record. Everything accepted is kept for inspection.
55	type failWriter struct {
56		buf        bytes.Buffer
57		allowBytes int
58		partial    int
59		err        error
60		failed     bool
61	}
62	
63	func (w *failWriter) Write(p []byte) (int, error) {
64		accepted := 0
65		if w.allowBytes > 0 {
66			n := len(p)
67			if n > w.allowBytes {
68				n = w.allowBytes
69			}
70			w.buf.Write(p[:n])
71			w.allowBytes -= n
72			accepted, p = n, p[n:]
73			if len(p) == 0 {
74				return accepted, nil
75			}
76		}
77		m := w.partial
78		if m > len(p) {
79			m = len(p)
80		}
81		w.buf.Write(p[:m])
82		w.failed = true
83		return accepted + m, w.err
84	}
85	
86	// decodeResults parses complete JSON-object-per-line output. A non-EOF
87	// decode error fails the test: healthy output must always be whole records.
88	func decodeResults(t *testing.T, data []byte) []map[string]any {
89		t.Helper()
90		var results []map[string]any
91		dec := json.NewDecoder(bytes.NewReader(data))
92		for {
93			var m map[string]any
94			if err := dec.Decode(&m); err != nil {
95				if errors.Is(err, io.EOF) {
96					return results
97				}
98				t.Fatalf("output must consist of whole result records, got decode error %v after %d records: %q", err, len(results), string(data))
99			}
100			results = append(results, m)
101		}
102	}
103	
104	// decodePrefix parses as many whole records as a possibly-truncated output
105	// contains; a write interruption is allowed to leave a non-record tail, so
106	// a trailing syntax error is expected rather than fatal.
107	func decodePrefix(t *testing.T, data []byte) []map[string]any {
108		t.Helper()
109		var results []map[string]any
110		dec := json.NewDecoder(bytes.NewReader(data))
111		for {
112			var m map[string]any
113			if err := dec.Decode(&m); err != nil {
114				if errors.Is(err, io.EOF) {
115					t.Fatalf("expected truncated trailing output, got a clean record boundary")
116				}
117				return results
118			}
119			results = append(results, m)
120		}
121	}
122	
123	func validLog(action string) string {
124		return `{"timestamp":"2026-01-02T00:00:00Z","action":"` + action + `"}`
125	}
126	
127	func bigValidLog(action string) string {
128		return fmt.Sprintf(`{"timestamp":"2026-01-02T00:00:00Z","action":%q,"pad":%q}`,
129			action, strings.Repeat("p", 5000))
130	}
131	
132	// encodedRecord is the exact byte form NormalizeReader writes for one line
133	// (json.Encoder appends a newline), used to script writer byte budgets.
134	func encodedRecord(t *testing.T, lineNo int, raw string) []byte {
135		t.Helper()
136		b, err := json.Marshal(NormalizeLine(lineNo, []byte(raw)))
137		if err != nil {
138			t.Fatal(err)
139		}
140		return append(b, '\n')
141	}
142	
143	// A field-invalid line embedded in a healthy stream produces a failure
144	// result carrying its original line number, later valid lines keep coming,
145	// and the returned error is nil: per-line failures are not I/O failures.
146	func TestNormalizeIOInvalidLineIsNotStreamError(t *testing.T) {
147		input := validLog("a") + "\n" +
148			`{"timestamp":"not-a-time","action":"b"}` + "\n" +
149			validLog("c") + "\n"
150		var out bytes.Buffer
151		failures, err := NormalizeReader(strings.NewReader(input), &out)
152		if err != nil {
153			t.Fatalf("healthy stream must return nil error, got %v", err)
154		}
155		if errors.Is(err, ErrLogRead) || errors.Is(err, ErrLogWrite) {
156			t.Fatalf("nil error cannot match an I/O sentinel: %v", err)
157		}
158		if failures != 1 {
159			t.Fatalf("only the invalid log must count as a failure, got %d", failures)
160		}
161		results := decodeResults(t, out.Bytes())
162		if len(results) != 3 {
163			t.Fatalf("expected 3 results, got %#v", results)
164		}
165		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
166			t.Fatalf("line 1 mismatch: %#v", results[0])
167		}
168		if results[1]["line"] != float64(2) || results[1]["ok"] != false {
169			t.Fatalf("invalid line must keep line number 2: %#v", results[1])
170		}
171		if msg, _ := results[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
172			t.Fatalf("per-line error explanation must survive in output, got %q", msg)
173		}
174		if _, exists := results[1]["event"]; exists {
175			t.Fatalf("failed line must not carry an event: %#v", results[1])
176		}
177		if results[2]["line"] != float64(3) || results[2]["ok"] != true {
178			t.Fatalf("valid line 3 must still be emitted: %#v", results[2])
179		}
180		if eventOf(t, results[2])["action"] != "c" {
181			t.Fatalf("line 3 must preserve order and content")
182		}
183	}
184	
185	// When the input stream fails after whole lines, everything already read is
186	// processed in order and flushed; the read error is reported wrapped with
187	// ErrLogRead, the failure count covers only genuinely invalid complete
188	// lines, and an unterminated fragment delivered with the failure is neither
189	// normalized, counted, nor emitted.
190	func TestNormalizeIOReadErrorAfterCompleteLines(t *testing.T) {
191		complete := validLog("a") + "\n" +
192			`{"timestamp":"not-a-time","action":"b"}` + "\n" +
193			validLog("c") + "\n"
194		cases := []struct {
195			name     string
196			fragment []byte
197		}{
198			{"error carries an unterminated fragment", []byte(`{"timestamp":"FRAGMENT-MARKER","action":`)},
199			{"error stands alone after a newline", nil},
200			{"error carries only blank bytes", []byte("   ")},
201		}
202		for _, tc := range cases {
203			t.Run(tc.name, func(t *testing.T) {
204				src := &scriptReader{steps: []scriptStep{
205					{data: []byte(complete)},
206					{data: tc.fragment, err: errSimulatedRead},
207				}}
208				var out bytes.Buffer
209				failures, err := NormalizeReader(src, &out)
210				if err == nil {
211					t.Fatalf("read failure must be returned, not treated as success")
212				}
213				if !errors.Is(err, ErrLogRead) {
214					t.Fatalf("error must match ErrLogRead, got %v", err)
215				}
216				if !errors.Is(err, errSimulatedRead) {
217					t.Fatalf("underlying read cause must stay reachable, got %v", err)
218				}
219				if errors.Is(err, ErrLogWrite) {
220					t.Fatalf("a healthy writer must not tag the error as a write failure: %v", err)
221				}
222				if !strings.Contains(err.Error(), errSimulatedRead.Error()) {
223					t.Fatalf("error text must stay recognizable as the read cause, got %q", err.Error())
224				}
225				if failures != 1 {
226					t.Fatalf("read fault must not count as a log; only the one bad line counts, got %d", failures)
227				}
228				results := decodeResults(t, out.Bytes())
229				if len(results) != 3 {
230					t.Fatalf("only the 3 complete lines may be emitted, got %#v", results)
231				}
232				if results[0]["line"] != float64(1) || results[0]["ok"] != true ||
233					results[1]["line"] != float64(2) || results[1]["ok"] != false ||
234					results[2]["line"] != float64(3) || results[2]["ok"] != true {
235					t.Fatalf("processed lines must keep order, numbers and outcomes: %#v", results)
236				}
237				if msg, _ := results[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
238					t.Fatalf("per-line error explanation must be preserved, got %q", msg)
239				}
240				if bytes.Contains(out.Bytes(), []byte("FRAGMENT-MARKER")) {
241					t.Fatalf("unterminated fragment must not produce an event or line error: %q", out.String())
242				}
243			})
244		}
245	}
246	
247	// A read failure before any complete line yields no results and no failure
248	// count, but the stream error still reaches the caller.
249	func TestNormalizeIOReadErrorBeforeAnyLine(t *testing.T) {
250		src := &scriptReader{steps: []scriptStep{
251			{data: []byte(`{"timestamp":"cut off`), err: errSimulatedRead},
252		}}
253		var out bytes.Buffer
254		failures, err := NormalizeReader(src, &out)
255		if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
256			t.Fatalf("want ErrLogRead wrapping the cause, got %v", err)
257		}
258		if failures != 0 {
259			t.Fatalf("an unread stream has no failed logs, got %d", failures)
260		}
261		if out.Len() != 0 {
262			t.Fatalf("no complete line means no output, got %q", out.String())
263		}
264	}
265	
266	// The writer fails only when the final buffered batch is flushed at input
267	// end: the caller must still receive ErrLogWrite. When every log was valid
268	// the failure count stays zero; when invalid logs were already counted,
269	// that count must not be reset.
270	func TestNormalizeIOWriteErrorOnFinalFlush(t *testing.T) {
271		cases := []struct {
272			name         string
273			input        string
274			wantFailures int
275		}{
276			{
277				name:         "all logs valid",
278				input:        validLog("a") + "\n" + validLog("b") + "\n",
279				wantFailures: 0,
280			},
281			{
282				name: "invalid log already counted",
283				input: validLog("a") + "\n" +
284					`{"timestamp":"not-a-time","action":"b"}` + "\n" +
285					validLog("c") + "\n",
286				wantFailures: 1,
287			},
288		}
289		for _, tc := range cases {
290			t.Run(tc.name, func(t *testing.T) {
291				w := &failWriter{err: errSimulatedWrite} // reject every Write
292				failures, err := NormalizeReader(strings.NewReader(tc.input), w)
293				if !errors.Is(err, ErrLogWrite) || !errors.Is(err, errSimulatedWrite) {
294					t.Fatalf("want ErrLogWrite wrapping the cause, got %v", err)
295				}
296				if errors.Is(err, ErrLogRead) {
297					t.Fatalf("a healthy reader must not tag the error as a read failure: %v", err)
298				}
299				if !w.failed {
300					t.Fatalf("the final flush must actually have reached the failing writer")
301				}
302				if failures != tc.wantFailures {
303					t.Fatalf("write fault must not alter the failure count: got %d, want %d", failures, tc.wantFailures)
304				}
305			})
306		}
307	}
308	
309	// A write failure in the middle of processing (records larger than the
310	// internal buffer go straight to the underlying writer) stops the run with
311	// ErrLogWrite; whatever reached the writer may end mid-record, and the write
312	// fault never fabricates an ordinary log failure or moves the count.
313	func TestNormalizeIOWriteErrorMidStream(t *testing.T) {
314		t.Run("all valid logs", func(t *testing.T) {
315			line1 := bigValidLog("a")
316			line2 := bigValidLog("b")
317			encoded1 := encodedRecord(t, 1, line1)
318			if len(encoded1) <= 4096 {
319				t.Fatalf("test setup: encoded line must exceed the 4096-byte buffer, got %d", len(encoded1))
320			}
321			// Line 1 is accepted whole; the write for line 2 takes 120 bytes
322			// and then fails, leaving a truncated non-record tail.
323			w := &failWriter{allowBytes: len(encoded1), partial: 120, err: errSimulatedWrite}
324			failures, err := NormalizeReader(strings.NewReader(line1+"\n"+line2+"\n"), w)
325			if !errors.Is(err, ErrLogWrite) || !errors.Is(err, errSimulatedWrite) {
326				t.Fatalf("want ErrLogWrite wrapping the cause, got %v", err)
327			}
328			if failures != 0 {
329				t.Fatalf("write fault must not add a log failure, got %d", failures)
330			}
331			results := decodePrefix(t, w.buf.Bytes())
332			if len(results) != 1 || results[0]["ok"] != true {
333				t.Fatalf("only the fully written line 1 may decode whole: %#v", results)
334			}
335			if eventOf(t, results[0])["action"] != "a" {
336				t.Fatalf("written record must be the genuine first log")
337			}
338			if w.buf.Len() != len(encoded1)+120 {
339				t.Fatalf("the interrupted write must leave exactly 120 partial bytes beyond line 1, got total %d", w.buf.Len())
340			}
341		})
342	
343		t.Run("invalid log counted before the write fault", func(t *testing.T) {
344			line1 := bigValidLog("a")
345			encoded1 := encodedRecord(t, 1, line1)
346			invalid := `{"timestamp":"not-a-time","action":"b"}` // small failure result stays buffered
347			line3 := bigValidLog("c")
348			// Line 1 goes out whole; the next physical write (the buffered
349			// failure result, flushed while line 3 is encoded) accepts a few
350			// bytes and then fails.
351			w := &failWriter{allowBytes: len(encoded1) + 5, err: errSimulatedWrite}
352			failures, err := NormalizeReader(strings.NewReader(line1+"\n"+invalid+"\n"+line3+"\n"), w)
353			if !errors.Is(err, ErrLogWrite) {
354				t.Fatalf("want ErrLogWrite, got %v", err)
355			}
356			if failures != 1 {
357				t.Fatalf("the invalid log must still count exactly once after the write fault, got %d", failures)
358			}
359			results := decodePrefix(t, w.buf.Bytes())
360			if len(results) != 1 || results[0]["ok"] != true {
361				t.Fatalf("only line 1 should have left a whole record: %#v", results)
362			}
363		})
364	}
365	
366	// If the reader has already failed and flushing the buffered results fails
367	// too, the caller must still receive the original read cause: the later
368	// write error must not mask it.
369	func TestNormalizeIOReadErrorWinsOverFlushError(t *testing.T) {
370		complete := validLog("a") + "\n" +
371			`{"timestamp":"not-a-time","action":"b"}` + "\n" +
372			validLog("c") + "\n"
373		src := &scriptReader{steps: []scriptStep{
374			{data: []byte(complete)},
375			{data: []byte(`{"truncated":`), err: errSimulatedRead},
376		}}
377		// Small records stay in the internal buffer, so the first physical
378		// write is the shutdown flush, which fails with a distinct error.
379		w := &failWriter{err: errSimulatedWrite}
380		failures, err := NormalizeReader(src, w)
381		if err == nil {
382			t.Fatalf("expected the read failure, got nil")
383		}
384		if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
385			t.Fatalf("the original read error must reach the caller, got %v", err)
386		}
387		if errors.Is(err, ErrLogWrite) || errors.Is(err, errSimulatedWrite) {
388			t.Fatalf("the later flush error must not replace the read cause: %v", err)
389		}
390		msg := err.Error()
391		if !strings.Contains(msg, errSimulatedRead.Error()) {
392			t.Fatalf("error text must name the read cause first, got %q", msg)
393		}
394		if !strings.Contains(msg, errSimulatedWrite.Error()) {
395			t.Fatalf("the shutdown write failure should still be visible in the message, got %q", msg)
396		}
397		if failures != 1 {
398			t.Fatalf("only the one invalid complete line counts, got %d", failures)
399		}
400	}
401	
402	// A clean EOF after a final newline-less complete line is normal completion:
403	// the line is processed, results flush, and no error is reported.
404	func TestNormalizeIOCleanEOFWithoutFinalNewline(t *testing.T) {
405		input := validLog("a") + "\n" + validLog("b") // last line has no "\n"
406		var out bytes.Buffer
407		failures, err := NormalizeReader(strings.NewReader(input), &out)
408		if err != nil {
409			t.Fatalf("clean EOF must not be an error, got %v", err)
410		}
411		if failures != 0 {
412			t.Fatalf("valid logs must report zero failures, got %d", failures)
413		}
414		results := decodeResults(t, out.Bytes())
415		if len(results) != 2 || results[1]["ok"] != true {
416			t.Fatalf("final line without newline must be processed normally: %#v", results)
417		}
418		if eventOf(t, results[1])["action"] != "b" {
419			t.Fatalf("final line content mismatch: %#v", results[1])
420		}
421	}
